<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Announcements'; require_role(['admin']); require_once __DIR__.'/../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();try{$title=trim($_POST['title']);$body=trim($_POST['body']);$st=$pdo->prepare("INSERT INTO announcements(title,body,audience,expires_at,created_by) VALUES(?,?,?,?,?)");$st->execute([$title,$body,$_POST['audience'],$_POST['expires_at']?:null,user()['id']]);$st=$pdo->prepare("INSERT INTO community_posts(author_id,title,body,post_type) VALUES(?,?,?,'announcement')");$st->execute([user()['id'],$title,$body]);$pdo->commit();$saved=true;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not publish announcement.';}}
$rows=$pdo->query("SELECT * FROM announcements ORDER BY published_at DESC")->fetchAll();
?><h2>Announcements</h2><?php if(!empty($saved)): ?><div class="alert alert-success">Announcement published.</div><?php endif;?><div class="card p-4 mb-4"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label>Title</label><input class="form-control" name="title" required></div><div class="col-md-3"><label>Audience</label><select class="form-select" name="audience"><option>all</option><option>parents</option><option>students</option><option>teachers</option></select></div><div class="col-md-3"><label>Expires</label><input class="form-control" type="datetime-local" name="expires_at"></div><div class="col-12"><label>Message</label><textarea class="form-control" name="body" rows="4" required></textarea></div><div class="col-12"><button class="btn btn-primary">Publish</button></div></div></form></div>
<?php foreach($rows as $r): ?><div class="card p-3 mb-2"><h5><?=e($r['title'])?></h5><div class="small text-muted"><?=e($r['audience'])?> · <?=e($r['published_at'])?></div><p class="mb-0 mt-2"><?=nl2br(e($r['body']))?></p></div><?php endforeach;?>
<?php require __DIR__.'/../includes/footer.php';